BEGIN TRANSACTION;
CREATE TABLE audit(operation_id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(household_id), actor_id TEXT NOT NULL, action TEXT NOT NULL, command_key TEXT NOT NULL, detail TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE calendar_preferences(household_id TEXT NOT NULL, member_id TEXT NOT NULL, week_start TEXT NOT NULL DEFAULT 'monday' CHECK(week_start IN ('monday','sunday')), revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>=1), PRIMARY KEY(household_id,member_id), FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,member_id));
CREATE TABLE household_policy(household_id TEXT PRIMARY KEY REFERENCES households(household_id), mapping_mode TEXT NOT NULL, target_ha_user_id TEXT, revision INTEGER NOT NULL CHECK(revision>=1), adjustments TEXT NOT NULL, CHECK((mapping_mode='all_ha_administrators' AND target_ha_user_id IS NULL) OR (mapping_mode IN ('setup_administrator','selected_ha_user') AND target_ha_user_id IS NOT NULL)));
CREATE TABLE households(household_id TEXT PRIMARY KEY, singleton INTEGER NOT NULL DEFAULT 1 UNIQUE CHECK(singleton=1), name TEXT NOT NULL, time_zone TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>=1), materialization_horizon_days INTEGER NOT NULL DEFAULT 60 CHECK(typeof(materialization_horizon_days)='integer' AND materialization_horizon_days BETWEEN 7 AND 366), repeated_time TEXT NOT NULL DEFAULT 'first_instant' CHECK(repeated_time IN ('first_instant','second_instant')));
CREATE TABLE installation(singleton INTEGER PRIMARY KEY CHECK(singleton=1), instance_id TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('stable','edge')));
CREATE TABLE inventory_effects(household_id TEXT NOT NULL, effect_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('reservation','demand')), reference_id TEXT NOT NULL, origin_id TEXT, occurrence_id TEXT, line_id TEXT, remaining INTEGER NOT NULL CHECK(remaining BETWEEN 0 AND 999999999999999999), revision INTEGER NOT NULL CHECK(revision>=1), PRIMARY KEY(household_id,effect_id), UNIQUE(household_id,occurrence_id,reference_id,kind), CHECK((origin_id IS NOT NULL AND occurrence_id IS NOT NULL AND line_id IS NOT NULL) OR (kind='demand' AND origin_id IS NULL AND occurrence_id IS NULL AND line_id IS NULL)), FOREIGN KEY(household_id,reference_id) REFERENCES inventory_materials(household_id,reference_id), FOREIGN KEY(household_id,origin_id) REFERENCES task_occurrences(household_id,occurrence_id), FOREIGN KEY(household_id,occurrence_id) REFERENCES task_occurrences(household_id,occurrence_id)) STRICT;
CREATE TABLE inventory_materials(household_id TEXT NOT NULL REFERENCES households(household_id), reference_id TEXT NOT NULL, product_id TEXT NOT NULL, unit_id TEXT NOT NULL, location_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision=1), precision INTEGER NOT NULL CHECK(precision BETWEEN 0 AND 6), label TEXT NOT NULL, balance INTEGER NOT NULL CHECK(balance BETWEEN 0 AND 999999999999999999), PRIMARY KEY(household_id,reference_id), UNIQUE(household_id,product_id,location_id)) STRICT;
CREATE TABLE inventory_movements(position INTEGER PRIMARY KEY, household_id TEXT NOT NULL, reference_id TEXT NOT NULL, movement_id TEXT NOT NULL, source_key TEXT NOT NULL, member_id TEXT NOT NULL, delta INTEGER NOT NULL CHECK(delta BETWEEN -999999999999999999 AND 999999999999999999 AND delta!=0), created_at INTEGER NOT NULL CHECK(created_at>=0), reason TEXT NOT NULL, posting TEXT, corrects TEXT, kind TEXT NOT NULL, UNIQUE(household_id,movement_id), UNIQUE(household_id,source_key), UNIQUE(household_id,reference_id,movement_id), UNIQUE(household_id,corrects), CHECK((kind='intake' AND posting IS NULL AND corrects IS NULL AND delta>0) OR (kind='adjustment' AND posting IS NULL AND corrects IS NULL) OR (kind='intake_correction' AND posting IS NULL AND corrects IS NOT NULL AND delta<0) OR (kind='task_consumption' AND posting IS NOT NULL AND corrects IS NULL AND delta<0) OR (kind='task_correction' AND posting IS NOT NULL AND corrects IS NOT NULL)), FOREIGN KEY(household_id,reference_id) REFERENCES inventory_materials(household_id,reference_id), FOREIGN KEY(household_id,reference_id,corrects) REFERENCES inventory_movements(household_id,reference_id,movement_id), FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,member_id)) STRICT;
CREATE TABLE inventory_products(household_id TEXT NOT NULL, product_id TEXT NOT NULL, reference_id TEXT NOT NULL, name TEXT NOT NULL, base_unit TEXT NOT NULL CHECK(base_unit IN ('piece','gram','millilitre')), PRIMARY KEY(household_id,product_id), UNIQUE(household_id,reference_id), FOREIGN KEY(household_id,reference_id) REFERENCES inventory_materials(household_id,reference_id)) STRICT;
CREATE TABLE inventory_replenishment(household_id TEXT NOT NULL, product_id TEXT NOT NULL, minimum INTEGER NOT NULL CHECK(minimum BETWEEN 0 AND 999999999999999999), target INTEGER NOT NULL CHECK(target BETWEEN minimum AND 999999999999999999), revision INTEGER NOT NULL CHECK(revision>0), PRIMARY KEY(household_id,product_id), FOREIGN KEY(household_id,product_id) REFERENCES inventory_products(household_id,product_id)) STRICT;
CREATE TABLE member_preferences(member_id TEXT PRIMARY KEY NOT NULL, household_id TEXT NOT NULL, locale TEXT CHECK(locale IS NULL OR locale IN ('en','es')), routine_participation_summaries INTEGER NOT NULL CHECK(typeof(routine_participation_summaries)='integer' AND routine_participation_summaries IN (0,1)), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,member_id));
CREATE TABLE member_presentations(member_id TEXT PRIMARY KEY NOT NULL, household_id TEXT NOT NULL, alias TEXT, revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,member_id), CHECK(alias IS NULL OR (typeof(alias)='text' AND length(alias) BETWEEN 1 AND 80)));
CREATE TABLE members(member_id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(household_id), ha_user_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('administrator','adult','restricted','viewer')), status TEXT NOT NULL CHECK(status IN ('pending','active','suspended','archived')), revision INTEGER NOT NULL CHECK(revision>=1), exceptions TEXT NOT NULL, UNIQUE(household_id,ha_user_id));
CREATE TABLE outbox(position INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, household_id TEXT NOT NULL REFERENCES households(household_id), event_type TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL, delivered INTEGER NOT NULL DEFAULT 0 CHECK(delivered IN (0,1)));
CREATE TABLE point_allocation_settings(household_id TEXT NOT NULL REFERENCES households,scope TEXT NOT NULL, definition_id TEXT, revision INTEGER NOT NULL CHECK(revision>=1),document TEXT CHECK(document IS NULL OR json_valid(document)),CHECK((definition_id IS NULL AND scope='household' AND document IS NOT NULL) OR (definition_id IS NOT NULL AND scope='task:'||definition_id)),PRIMARY KEY(household_id,scope), FOREIGN KEY(household_id,definition_id) REFERENCES task_definitions(household_id,definition_id));
CREATE TABLE point_completion_allocations(position INTEGER PRIMARY KEY AUTOINCREMENT,household_id TEXT NOT NULL REFERENCES households, cycle_id TEXT NOT NULL REFERENCES task_cycles, definition_id TEXT NOT NULL, document TEXT NOT NULL CHECK(json_valid(document)),UNIQUE(household_id,cycle_id), FOREIGN KEY(household_id,definition_id) REFERENCES task_definitions(household_id,definition_id));
CREATE TABLE points_task_receipts(household_id TEXT NOT NULL REFERENCES households,event_id TEXT NOT NULL REFERENCES receipts(operation_id), position INTEGER NOT NULL REFERENCES outbox(position), cycle_id TEXT NOT NULL REFERENCES task_cycles, definition_id TEXT NOT NULL, fingerprint TEXT NOT NULL CHECK(length(fingerprint)=64 AND fingerprint NOT GLOB '*[^0-9a-f]*'), effect INTEGER NOT NULL CHECK(effect IN (0,1,2)), document TEXT, PRIMARY KEY(household_id,event_id), UNIQUE(household_id,position), CHECK((effect=0 AND document IS NULL) OR (effect>0 AND document IS NOT NULL AND json_valid(document))), FOREIGN KEY(household_id,definition_id) REFERENCES task_definitions(household_id,definition_id));
CREATE TABLE receipts(household_id TEXT NOT NULL REFERENCES households(household_id), actor_id TEXT NOT NULL, action TEXT NOT NULL, command_key TEXT NOT NULL, payload_fingerprint TEXT NOT NULL, operation_id TEXT NOT NULL UNIQUE, result TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(household_id,actor_id,action,command_key));
CREATE TABLE recovery_requests(request_id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(household_id), target_ha_user_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>=1), state TEXT NOT NULL CHECK(state IN ('pending','approved','consumed','canceled')), created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, detail TEXT NOT NULL);
CREATE TABLE recurrence_frontiers(household_id TEXT PRIMARY KEY NOT NULL REFERENCES households(household_id), after_schedule_id TEXT, revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), selected_at INTEGER NOT NULL CHECK(typeof(selected_at)='integer' AND selected_at>=0), document TEXT NOT NULL);
CREATE TABLE recurrence_progress(schedule_id TEXT PRIMARY KEY NOT NULL, household_id TEXT NOT NULL, pattern_revision INTEGER NOT NULL CHECK(typeof(pattern_revision)='integer' AND pattern_revision>=1), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), timing_kind TEXT NOT NULL CHECK(timing_kind IN ('fixed_calendar','completion_relative')), document TEXT NOT NULL, UNIQUE(household_id,schedule_id,pattern_revision,timing_kind), FOREIGN KEY(household_id,schedule_id,pattern_revision,timing_kind) REFERENCES recurrence_rules(household_id,schedule_id,pattern_revision,timing_kind) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE recurrence_progress_evidence(household_id TEXT NOT NULL, schedule_id TEXT NOT NULL, progress_revision INTEGER NOT NULL CHECK(typeof(progress_revision)='integer' AND progress_revision>=1), operation_id TEXT NOT NULL, evidence_fingerprint TEXT NOT NULL, PRIMARY KEY(household_id,schedule_id), FOREIGN KEY(household_id,schedule_id,progress_revision) REFERENCES recurrence_progress(household_id,schedule_id,revision) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE recurrence_relative_closures(household_id TEXT NOT NULL, closure_key TEXT NOT NULL, operation_id TEXT NOT NULL UNIQUE, document TEXT NOT NULL, PRIMARY KEY(household_id,closure_key));
CREATE TABLE recurrence_relative_inbox(household_id TEXT NOT NULL REFERENCES households(household_id), position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=1), event_key TEXT NOT NULL, operation_id TEXT NOT NULL UNIQUE, actor_id TEXT NOT NULL, cycle_key TEXT NOT NULL, source_schedule_id TEXT, source_terminal INTEGER NOT NULL CHECK(typeof(source_terminal)='integer' AND source_terminal IN (0,1)), outcome_status TEXT, outcome_schedule_id TEXT, outcome_operation_id TEXT, outcome_occurrence_id TEXT, CHECK((outcome_status IS NULL)=(outcome_schedule_id IS NULL) AND (outcome_status IS NOT NULL OR (outcome_operation_id IS NULL AND outcome_occurrence_id IS NULL))), PRIMARY KEY(household_id,position), UNIQUE(household_id,event_key), FOREIGN KEY(household_id,source_schedule_id) REFERENCES recurrence_rules(household_id,schedule_id));
CREATE TABLE recurrence_relative_slots(household_id TEXT NOT NULL, slot_key TEXT NOT NULL, schedule_id TEXT NOT NULL, definition_id TEXT NOT NULL, pattern_revision INTEGER NOT NULL CHECK(typeof(pattern_revision)='integer' AND pattern_revision>=1), occurrence_id TEXT NOT NULL, source_occurrence_id TEXT, source_cycle_id TEXT, created_at INTEGER NOT NULL CHECK(typeof(created_at)='integer' AND created_at>=0), receipt_actor TEXT NOT NULL CHECK(receipt_actor='system:recurrence'), receipt_action TEXT NOT NULL CHECK(receipt_action='recurrence.materialize'), timing_kind TEXT NOT NULL CHECK(timing_kind='completion_relative'), document TEXT NOT NULL, PRIMARY KEY(household_id,slot_key), UNIQUE(household_id,occurrence_id), CHECK((source_occurrence_id IS NULL)=(source_cycle_id IS NULL)), FOREIGN KEY(household_id,schedule_id,definition_id,timing_kind) REFERENCES recurrence_rules(household_id,schedule_id,definition_id,timing_kind), FOREIGN KEY(household_id,definition_id,occurrence_id) REFERENCES task_occurrences(household_id,definition_id,occurrence_id), FOREIGN KEY(household_id,source_occurrence_id,source_cycle_id) REFERENCES task_cycles(household_id,occurrence_id,cycle_id), FOREIGN KEY(household_id,receipt_actor,receipt_action,slot_key) REFERENCES receipts(household_id,actor_id,action,command_key) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE recurrence_rules(schedule_id TEXT PRIMARY KEY NOT NULL, household_id TEXT NOT NULL, definition_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), pattern_revision INTEGER NOT NULL CHECK(typeof(pattern_revision)='integer' AND pattern_revision>=1 AND pattern_revision<=revision), state TEXT NOT NULL CHECK(state IN ('active','paused','retired')), timing_kind TEXT NOT NULL CHECK(timing_kind IN ('fixed_calendar','completion_relative')), document TEXT NOT NULL, UNIQUE(household_id,schedule_id), UNIQUE(household_id,schedule_id,definition_id), UNIQUE(household_id,schedule_id,pattern_revision,timing_kind), UNIQUE(household_id,schedule_id,definition_id,timing_kind), FOREIGN KEY(household_id,definition_id) REFERENCES task_definitions(household_id,definition_id), FOREIGN KEY(household_id,schedule_id,pattern_revision,timing_kind) REFERENCES recurrence_progress(household_id,schedule_id,pattern_revision,timing_kind) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE recurrence_slots(household_id TEXT NOT NULL, slot_key TEXT NOT NULL, schedule_id TEXT NOT NULL, definition_id TEXT NOT NULL, pattern_revision INTEGER NOT NULL CHECK(typeof(pattern_revision)='integer' AND pattern_revision>=1), occurrence_id TEXT NOT NULL, nominal_kind TEXT NOT NULL CHECK(nominal_kind IN ('date','time')), nominal_value TEXT NOT NULL, resolved_at INTEGER, created_at INTEGER NOT NULL CHECK(typeof(created_at)='integer' AND created_at>=0), receipt_actor TEXT NOT NULL CHECK(receipt_actor='system:recurrence'), receipt_action TEXT NOT NULL CHECK(receipt_action='recurrence.materialize'), timing_kind TEXT NOT NULL CHECK(timing_kind='fixed_calendar'), document TEXT NOT NULL, PRIMARY KEY(household_id,slot_key), UNIQUE(household_id,occurrence_id), CHECK((nominal_kind='date' AND resolved_at IS NULL) OR (nominal_kind='time' AND typeof(resolved_at)='integer' AND resolved_at>=0)), FOREIGN KEY(household_id,schedule_id,definition_id,timing_kind) REFERENCES recurrence_rules(household_id,schedule_id,definition_id,timing_kind), FOREIGN KEY(household_id,definition_id,occurrence_id) REFERENCES task_occurrences(household_id,definition_id,occurrence_id), FOREIGN KEY(household_id,receipt_actor,receipt_action,slot_key) REFERENCES receipts(household_id,actor_id,action,command_key) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE retained_operations(household_id TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, command_key TEXT NOT NULL, operation_id TEXT NOT NULL UNIQUE, position INTEGER NOT NULL UNIQUE CHECK(position>=1), current INTEGER NOT NULL CHECK(current IN (0,1)), archived_by TEXT, document TEXT NOT NULL, closed_recovery_id TEXT, PRIMARY KEY(household_id,actor_id,action,command_key));
CREATE TABLE reward_funding_changes(household_id TEXT NOT NULL, redemption_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>1), source TEXT NOT NULL CHECK(source IN ('points','cancellation')),source_id TEXT NOT NULL, stage TEXT NOT NULL CHECK(stage IN ('approved','funding_hold')),occurred_at INTEGER NOT NULL CHECK(occurred_at>=0), PRIMARY KEY(household_id,redemption_id,revision),UNIQUE(household_id,redemption_id,source,source_id),FOREIGN KEY(household_id,redemption_id) REFERENCES reward_redemptions(household_id,redemption_id));
CREATE TABLE reward_offers(household_id TEXT NOT NULL REFERENCES households,offer_id TEXT NOT NULL, document TEXT NOT NULL CHECK(json_valid(document)),PRIMARY KEY(household_id,offer_id));
CREATE TABLE reward_redemptions(position INTEGER PRIMARY KEY AUTOINCREMENT,household_id TEXT NOT NULL REFERENCES households, redemption_id TEXT NOT NULL,member_id TEXT NOT NULL, offer_id TEXT NOT NULL, cost_minor INTEGER NOT NULL CHECK(cost_minor>0),stage TEXT NOT NULL CHECK(stage IN ('requested','approved','funding_hold','delivered','cancelled')),document TEXT NOT NULL CHECK(json_valid(document)), UNIQUE(household_id,redemption_id),FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,member_id),FOREIGN KEY(household_id,offer_id) REFERENCES reward_offers(household_id,offer_id));
CREATE TABLE reward_settings(household_id TEXT PRIMARY KEY REFERENCES households,enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), revision INTEGER NOT NULL CHECK(revision>=1));
CREATE TABLE reward_spends(household_id TEXT NOT NULL, redemption_id TEXT NOT NULL,member_id TEXT NOT NULL, cost_minor INTEGER NOT NULL CHECK(cost_minor>0),posted_at INTEGER NOT NULL CHECK(posted_at>=0), title TEXT NOT NULL,PRIMARY KEY(household_id,redemption_id),FOREIGN KEY(household_id,redemption_id) REFERENCES reward_redemptions(household_id,redemption_id),FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,member_id));
CREATE TABLE shopping_extras(position INTEGER PRIMARY KEY, household_id TEXT NOT NULL, extra_id TEXT NOT NULL, product_id TEXT, name TEXT NOT NULL, base_unit TEXT NOT NULL CHECK(base_unit IN ('piece','gram','millilitre')), quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 999999999999999999), member_id TEXT NOT NULL, created_at INTEGER NOT NULL CHECK(created_at>=0), cleared_by TEXT, cleared_at INTEGER CHECK(cleared_at>=0), CHECK((cleared_by IS NULL) = (cleared_at IS NULL)), CHECK(product_id IS NOT NULL OR base_unit='piece'), UNIQUE(household_id,extra_id), FOREIGN KEY(household_id,product_id) REFERENCES inventory_products(household_id,product_id), FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,member_id), FOREIGN KEY(household_id,cleared_by) REFERENCES members(household_id,member_id)) STRICT;
CREATE TABLE shopping_purchases(position INTEGER PRIMARY KEY, household_id TEXT NOT NULL, purchase_id TEXT NOT NULL, product_id TEXT, name TEXT NOT NULL, base_unit TEXT NOT NULL CHECK(base_unit IN ('piece','gram','millilitre')), purchased INTEGER NOT NULL CHECK(purchased BETWEEN 1 AND 999999999999999999), received INTEGER NOT NULL CHECK(received BETWEEN 0 AND purchased), settled INTEGER NOT NULL CHECK(settled BETWEEN 0 AND received), revision INTEGER NOT NULL CHECK(revision>0), member_id TEXT NOT NULL, created_at INTEGER NOT NULL CHECK(created_at>=0), UNIQUE(household_id,purchase_id), CHECK(product_id IS NOT NULL OR (base_unit='piece' AND settled=received)), FOREIGN KEY(household_id,product_id) REFERENCES inventory_products(household_id,product_id), FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,member_id)) STRICT;
CREATE TABLE shopping_receipts(position INTEGER PRIMARY KEY, household_id TEXT NOT NULL, receipt_id TEXT NOT NULL, purchase_id TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 999999999999999999), member_id TEXT NOT NULL, created_at INTEGER NOT NULL CHECK(created_at>=0), movement_id TEXT, UNIQUE(household_id,receipt_id), UNIQUE(household_id,movement_id), FOREIGN KEY(household_id,purchase_id) REFERENCES shopping_purchases(household_id,purchase_id), FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,member_id), FOREIGN KEY(household_id,movement_id) REFERENCES inventory_movements(household_id,movement_id)) STRICT;
CREATE TABLE task_categories(category_id TEXT PRIMARY KEY NOT NULL, household_id TEXT NOT NULL REFERENCES households(household_id), label TEXT NOT NULL, label_key TEXT NOT NULL, revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), archived INTEGER NOT NULL CHECK(archived IN (0,1)));
CREATE TABLE task_cycles(cycle_id TEXT PRIMARY KEY NOT NULL, household_id TEXT NOT NULL REFERENCES households(household_id), occurrence_id TEXT NOT NULL, active_occurrence_id TEXT, recorded_by TEXT NOT NULL, verified_by TEXT, revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), closed_at INTEGER CHECK(closed_at IS NULL OR (typeof(closed_at)='integer' AND closed_at>=0)), document TEXT NOT NULL, UNIQUE(household_id,active_occurrence_id,cycle_id,revision), CHECK((closed_at IS NULL AND active_occurrence_id IS occurrence_id) OR (closed_at IS NOT NULL AND active_occurrence_id IS NULL)), FOREIGN KEY(household_id,occurrence_id) REFERENCES task_occurrences(household_id,occurrence_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(household_id,recorded_by) REFERENCES members(household_id,member_id), FOREIGN KEY(household_id,verified_by) REFERENCES members(household_id,member_id), FOREIGN KEY(household_id,active_occurrence_id,cycle_id,revision) REFERENCES task_occurrences(household_id,occurrence_id,current_cycle_id,current_cycle_revision) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE task_definitions(definition_id TEXT PRIMARY KEY NOT NULL, household_id TEXT NOT NULL REFERENCES task_policy(household_id), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), state TEXT NOT NULL CHECK(state IN ('draft','active','paused','archived')), document TEXT NOT NULL, UNIQUE(household_id,definition_id));
CREATE TABLE task_material_intents(intent_id TEXT PRIMARY KEY NOT NULL, household_id TEXT NOT NULL, occurrence_id TEXT NOT NULL, cycle_id TEXT NOT NULL, line_id TEXT NOT NULL, recorded_by TEXT NOT NULL, revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), state TEXT NOT NULL CHECK(state IN ('pending_recording','pending_authorization','pending_regularization','pending_processing','not_used','posted','corrected','dismissed')), document TEXT NOT NULL, UNIQUE(household_id,cycle_id,line_id), FOREIGN KEY(household_id,occurrence_id,cycle_id) REFERENCES task_cycles(household_id,occurrence_id,cycle_id), FOREIGN KEY(household_id,recorded_by) REFERENCES members(household_id,member_id));
CREATE TABLE task_missed_occurrence_settings(household_id TEXT NOT NULL, definition_id TEXT NOT NULL, policy TEXT NOT NULL CHECK(policy IN ('keep_visible','skip_after_review')), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), PRIMARY KEY(household_id,definition_id), FOREIGN KEY(household_id,definition_id) REFERENCES task_definitions(household_id,definition_id));
CREATE TABLE task_occurrences(occurrence_id TEXT PRIMARY KEY NOT NULL, household_id TEXT NOT NULL REFERENCES households(household_id), definition_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), state TEXT NOT NULL CHECK(state IN ('draft','available','assigned','in_progress','blocked','completed','cancelled','skipped')), current_cycle_id TEXT, current_cycle_revision INTEGER CHECK(current_cycle_revision IS NULL OR (typeof(current_cycle_revision)='integer' AND current_cycle_revision>=1)), document TEXT NOT NULL, UNIQUE(household_id,occurrence_id), UNIQUE(household_id,occurrence_id,current_cycle_id,current_cycle_revision), CHECK((state='completed' AND current_cycle_id IS NOT NULL AND current_cycle_revision IS NOT NULL) OR (state!='completed' AND current_cycle_id IS NULL AND current_cycle_revision IS NULL)), FOREIGN KEY(household_id,definition_id) REFERENCES task_definitions(household_id,definition_id), FOREIGN KEY(household_id,occurrence_id,current_cycle_id,current_cycle_revision) REFERENCES task_cycles(household_id,active_occurrence_id,cycle_id,revision) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE task_policy(household_id TEXT PRIMARY KEY NOT NULL REFERENCES households(household_id), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), document TEXT NOT NULL);
CREATE INDEX outbox_pending ON outbox(delivered,position);
CREATE INDEX recovery_pending ON recovery_requests(household_id,state,expires_at);
CREATE INDEX retained_recovery ON retained_operations(household_id,closed_recovery_id) WHERE current=0 AND closed_recovery_id IS NOT NULL;
CREATE UNIQUE INDEX task_member_scope ON members(household_id,member_id);
CREATE INDEX task_definitions_page ON task_definitions(household_id,state,definition_id);
CREATE INDEX task_occurrences_page ON task_occurrences(household_id,state,occurrence_id);
CREATE INDEX task_occurrences_definition ON task_occurrences(household_id,definition_id,occurrence_id);
CREATE INDEX task_cycles_page ON task_cycles(household_id,occurrence_id,cycle_id);
CREATE UNIQUE INDEX task_one_open_cycle ON task_cycles(household_id,occurrence_id) WHERE closed_at IS NULL;
CREATE UNIQUE INDEX task_cycle_material_scope ON task_cycles(household_id,occurrence_id,cycle_id);
CREATE INDEX task_material_cycle_page ON task_material_intents(household_id,cycle_id,intent_id);
CREATE INDEX task_cycle_event_page ON outbox(json_extract(payload,'$.cycle.cycle_id'),position);
CREATE INDEX task_occurrence_event_page ON outbox(json_extract(payload,'$.occurrence_id'),position);
CREATE INDEX task_dependency_ack_page ON outbox(json_extract(payload,'$.review.cause.dependent_cycle_id'),json_extract(payload,'$.review.cause.source_operation_id'),position);
CREATE UNIQUE INDEX recurrence_occurrence_scope ON task_occurrences(household_id,definition_id,occurrence_id);
CREATE UNIQUE INDEX recurrence_cycle_scope ON task_cycles(household_id,occurrence_id,cycle_id);
CREATE UNIQUE INDEX recurrence_progress_revision ON recurrence_progress(household_id,schedule_id,revision);
CREATE UNIQUE INDEX recurrence_current_definition ON recurrence_rules(household_id,definition_id) WHERE state!='retired';
CREATE INDEX recurrence_rules_page ON recurrence_rules(household_id,state,schedule_id);
CREATE INDEX recurrence_slots_page ON recurrence_slots(household_id,schedule_id,slot_key);
CREATE INDEX recurrence_relative_slots_page ON recurrence_relative_slots(household_id,schedule_id,slot_key);
CREATE INDEX recurrence_relative_pending ON recurrence_relative_inbox(household_id,position) WHERE outcome_status IS NULL;
CREATE INDEX recurrence_relative_pending_rule ON recurrence_relative_inbox(household_id,source_schedule_id,source_terminal DESC,position) WHERE outcome_status IS NULL;
CREATE UNIQUE INDEX task_categories_active_label ON task_categories(household_id,label_key) WHERE archived=0;
CREATE UNIQUE INDEX points_one_effect_per_cycle ON points_task_receipts(household_id,cycle_id,effect) WHERE effect>0;
CREATE INDEX points_definition_rotation ON points_task_receipts(household_id,definition_id,position) WHERE effect=1;
CREATE INDEX points_restored_award_closure ON retained_operations(household_id,json_extract(document,'$.event_payload.cycle.cycle_id'),position) WHERE current=0 AND (action='task.reopen' OR (action='task.verify' AND json_extract(document,'$.event_payload.cycle.verification')='rejected'));
CREATE INDEX inventory_reservations ON inventory_effects(household_id,reference_id) WHERE kind='reservation' AND remaining>0;
CREATE INDEX point_allocation_rotation ON point_completion_allocations(household_id,definition_id,position) WHERE json_extract(document,'$.policy.mode')='conserve_total';
CREATE INDEX reward_member_requests ON reward_redemptions(household_id,member_id,position);
CREATE INDEX reward_member_reservations ON reward_redemptions(household_id,member_id,stage) WHERE stage IN ('requested','approved','funding_hold');
CREATE INDEX reward_member_spending ON reward_spends(household_id,member_id,posted_at);
CREATE INDEX inventory_history ON inventory_movements(household_id,reference_id,position);
CREATE UNIQUE INDEX shopping_open_pantry ON shopping_purchases(household_id,product_id) WHERE product_id IS NOT NULL AND settled<purchased;
